import andrewaylett from 'eslint-config-andrewaylett';
import nextPlugin from '@next/eslint-plugin-next';
import globals from 'globals';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  {
    // `lib/wasm` is generated by `pnpm ui wasm`; `out` and `.next` are builds.
    ignores: [
      '**/node_modules/*',
      '.next/*',
      'out/*',
      'test-results/*',
      'playwright-report/*',
      'lib/wasm/*',
      'next-env.d.ts',
    ],
  },
  {
    languageOptions: {
      parserOptions: {
        projectService: {
          allowDefaultProject: ['*.mjs', '*.mts'],
        },
      },
      globals: { ...globals.browser, ...globals.node },
    },
  },
  nextPlugin.configs.recommended,
  {
    files: ['**/*.ts', '**/*.tsx', '**/*.mts'],
    ...andrewaylett.configs.recommendedWithReactWithTypes,
  },
  andrewaylett.configs.recommendedWithReact,
  {
    settings: {
      react: { version: 'detect' },
      'import/resolver': { node: true },
    },
    rules: {
      curly: ['error', 'all'],
      'unicorn/filename-case': 'off',
      'unicorn/no-null': 'off',
      'unicorn/no-await-expression-member': 'off',
      '@typescript-eslint/restrict-template-expressions': [
        'error',
        { allowBoolean: true, allowNumber: true },
      ],
      '@typescript-eslint/no-inferrable-types': 'off',
      '@typescript-eslint/no-import-type-side-effects': 'error',
      'import/consistent-type-specifier-style': 'off',
      'unicorn/no-array-sort': 'off',
      'unicorn/no-array-reverse': 'off',
      'import/no-duplicates': ['error', { 'prefer-inline': true }],
      'import/no-extraneous-dependencies': 'error',
      'react/react-in-jsx-scope': 'off',
      'react/jsx-uses-react': 'off',
    },
  },
  {
    // The code keeps what a handler needs in a ref written during render
    // (`latest.current = …`), because key handlers outlive a render. That is
    // deliberate, and the React Compiler isn't used, so its diagnostics about
    // it would only be noise.
    rules: {
      'react-hooks/refs': 'off',
      'react-hooks/set-state-in-effect': 'off',
      // `noUncheckedIndexedAccess` is on, so `!` is how a lookup that is known
      // to succeed is written; it would otherwise be a cast or a dead branch.
      '@typescript-eslint/no-non-null-assertion': 'off',
      // The ref'd props are declared as methods, and are called, not detached.
      '@typescript-eslint/unbound-method': 'off',
      // Backends share one interface, so the in-memory and static ones are
      // `async` with nothing to await, and have no-op methods where the app's
      // has work to do. Callers handle failures as `Error`s, not `unknown`.
      '@typescript-eslint/require-await': 'off',
      '@typescript-eslint/no-empty-function': 'off',
      '@typescript-eslint/use-unknown-in-catch-callback-variable': 'off',
      // Handlers written as `() => setX(…)` are everywhere and harmless.
      '@typescript-eslint/no-confusing-void-expression': 'off',
      // Defensive checks against what a webview or another device could send
      // that the types say can't happen.
      '@typescript-eslint/no-unnecessary-condition': 'off',
      // `navigator.platform` is deprecated, but nothing else says Mac reliably.
      '@typescript-eslint/no-deprecated': 'off',
      // `window` is what the page's own globals (`__quiddityRemote`) are
      // declared on, so `globalThis` doesn't see them.
      'unicorn/prefer-global-this': 'off',
      // `typeof window === 'undefined'` is how code that also runs on a server
      // asks: naming an undeclared global throws there.
      'unicorn/no-typeof-undefined': 'off',
      // `edited(undefined)` is a call, not a missing argument.
      'unicorn/no-useless-undefined': 'off',
      // `charCodeAt` is what a surrogate check wants: `codePointAt` of a high
      // surrogate that has its pair is the whole code point.
      'unicorn/prefer-code-point': 'off',
      // Tauri's `Channel` takes `onmessage` and isn't an `EventTarget`.
      'unicorn/prefer-add-event-listener': 'off',
      // `read<T>` is a cast at the cache's one door.
      '@typescript-eslint/no-unnecessary-type-parameters': 'off',
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { disallowTypeAnnotations: false, fixStyle: 'inline-type-imports' },
      ],
    },
  },
  {
    // The page under test is reached through `evaluate`, which hands back
    // whatever the page has, and `window.__quiddityRemote` has no types here.
    files: ['e2e/**', 'e2e-dev/**'],
    rules: {
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-unsafe-member-access': 'off',
      '@typescript-eslint/no-unsafe-call': 'off',
      '@typescript-eslint/no-unsafe-return': 'off',
      '@typescript-eslint/no-unsafe-argument': 'off',
      '@typescript-eslint/require-await': 'off',
      // Playwright's fixtures take a callback called `use`, which isn't a hook.
      'react-hooks/rules-of-hooks': 'off',
      'unicorn/no-unreadable-array-destructuring': 'off',
    },
  },
  {
    files: ['e2e/**', 'e2e-dev/**', 'playwright.config.ts'],
    rules: {
      'import/no-extraneous-dependencies': ['error', { devDependencies: true }],
      'import/export': 'off',
      'no-duplicate-imports': 'off',
    },
  },
);
